// Validate incoming Meta webhook request and determine event type
const items = $input.all();
const results = [];

for (const item of items) {
  const body = item.json.body || item.json;
  const query = item.json.query || {};
  const method = item.json.headers?.['x-http-method'] || 'POST';

  // Handle GET verification request from Meta
  if (query['hub.mode'] === 'subscribe' && query['hub.verify_token']) {
    results.push({
      json: {
        eventType: 'verification',
        challenge: query['hub.challenge'] || '',
        verifyToken: query['hub.verify_token'],
        mode: query['hub.mode']
      }
    });
    continue;
  }

  // Validate webhook payload structure
  if (!body.object || body.object !== 'whatsapp_business_account') {
    results.push({
      json: {
        eventType: 'invalid',
        error: 'Invalid webhook payload: missing or wrong object field',
        rawBody: JSON.stringify(body).substring(0, 500)
      }
    });
    continue;
  }

  if (!body.entry || !Array.isArray(body.entry) || body.entry.length === 0) {
    results.push({
      json: {
        eventType: 'invalid',
        error: 'Invalid webhook payload: missing entry array'
      }
    });
    continue;
  }

  // Process each entry and change
  for (const entry of body.entry) {
    const changes = entry.changes || [];
    for (const change of changes) {
      const value = change.value || {};

      if (value.messages && value.messages.length > 0) {
        for (const message of value.messages) {
          results.push({
            json: {
              eventType: 'message',
              wabaId: entry.id,
              phoneNumberId: value.metadata?.phone_number_id || '',
              displayPhone: value.metadata?.display_phone_number || '',
              message: message,
              contacts: value.contacts || [],
              timestamp: message.timestamp
            }
          });
        }
      } else if (value.statuses && value.statuses.length > 0) {
        for (const status of value.statuses) {
          results.push({
            json: {
              eventType: 'status',
              wabaId: entry.id,
              phoneNumberId: value.metadata?.phone_number_id || '',
              status: status
            }
          });
        }
      } else {
        results.push({
          json: {
            eventType: 'unknown',
            wabaId: entry.id,
            value: value
          }
        });
      }
    }
  }
}

return results.length > 0 ? results : [{ json: { eventType: 'empty' } }];

// Normalize inbound WhatsApp message into a standard format
const item = $input.first();
const msg = item.json.message;
const contacts = item.json.contacts || [];
const contact = contacts.length > 0 ? contacts[0] : {};

let messageBody = '';
let messageType = msg.type || 'unknown';

switch (messageType) {
  case 'text':
    messageBody = msg.text?.body || '';
    break;
  case 'image':
    messageBody = msg.image?.caption || '[Image]';
    break;
  case 'document':
    messageBody = msg.document?.caption || '[Document]';
    break;
  case 'audio':
    messageBody = '[Audio message]';
    break;
  case 'video':
    messageBody = msg.video?.caption || '[Video]';
    break;
  case 'location':
    messageBody = `[Location: ${msg.location?.latitude}, ${msg.location?.longitude}]`;
    break;
  case 'contacts':
    messageBody = '[Contact shared]';
    break;
  case 'interactive':
    if (msg.interactive?.type === 'button_reply') {
      messageBody = msg.interactive.button_reply?.title || '';
    } else if (msg.interactive?.type === 'list_reply') {
      messageBody = msg.interactive.list_reply?.title || '';
    }
    break;
  case 'button':
    messageBody = msg.button?.text || '';
    break;
  case 'reaction':
    messageBody = `[Reaction: ${msg.reaction?.emoji || ''}]`;
    break;
  default:
    messageBody = `[Unsupported message type: ${messageType}]`;
}

return [{
  json: {
    whatsappMessageId: msg.id || '',
    senderWaId: msg.from || '',
    senderName: contact.profile?.name || '',
    senderPhone: contact.wa_id || msg.from || '',
    timestamp: msg.timestamp || '',
    messageType: messageType,
    messageBody: messageBody,
    rawMessage: msg,
    phoneNumberId: item.json.phoneNumberId || '',
    wabaId: item.json.wabaId || ''
  }
}];

// Verify the token and prepare the challenge response
const item = $input.first();
const expectedToken = $env.META_WEBHOOK_VERIFY_TOKEN || '';
const receivedToken = item.json.verifyToken || '';

if (!expectedToken) {
  throw new Error('META_WEBHOOK_VERIFY_TOKEN environment variable not set');
}

if (receivedToken !== expectedToken) {
  throw new Error('Webhook verification failed: token mismatch');
}

return [{
  json: {
    challenge: parseInt(item.json.challenge) || item.json.challenge
  }
}];
